BEGIN
 IF TG_OP='UPDATE' THEN
  IF NEW.plant_id IS NOT DISTINCT FROM OLD.plant_id AND NEW.organization_id IS NOT DISTINCT FROM OLD.organization_id AND NEW.role IS NOT DISTINCT FROM OLD.role THEN RETURN NEW; END IF;
 END IF;
 IF NEW.plant_id IS NOT NULL AND EXISTS (
  SELECT 1 FROM plants p LEFT JOIN organizations o ON o.id=p.organization_id
  WHERE p.id=NEW.plant_id AND (p.archived_at IS NOT NULL OR o.archived_at IS NOT NULL)
 ) THEN RAISE EXCEPTION 'Cannot allocate a user to an archived plant or organization' USING ERRCODE='23514'; END IF;
 IF NEW.organization_id IS NOT NULL AND EXISTS (SELECT 1 FROM organizations WHERE id=NEW.organization_id AND archived_at IS NOT NULL)
 THEN RAISE EXCEPTION 'Cannot allocate a user to an archived organization' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: operational_evidence_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.operational_evidence_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE oid uuid; s text;
BEGIN
 IF TG_OP='DELETE' THEN oid=OLD.work_order_id; ELSE oid=NEW.work_order_id; END IF;
 IF TG_OP='UPDATE' AND OLD.work_order_id IS DISTINCT FROM NEW.work_order_id THEN RAISE EXCEPTION 'Evidence cannot move between orders'; END IF;
 IF oid IS NOT NULL THEN
  SELECT status INTO s FROM work_orders WHERE id=oid FOR UPDATE;
  IF s='CLOSED' THEN RAISE EXCEPTION 'Closed order evidence is immutable'; END IF;
  IF TG_TABLE_NAME='production_logs' AND s<>'IN_PROGRESS' THEN RAISE EXCEPTION 'Production requires IN_PROGRESS order'; END IF;
  UPDATE work_orders SET revision=revision+1, shortfall_approval=CASE WHEN TG_TABLE_NAME='production_logs' THEN NULL ELSE shortfall_approval END, reviewed_snapshot=NULL, reviewed_by=NULL,
    status=CASE WHEN status='REVIEWED' THEN 'COMPLETED' ELSE status END WHERE id=oid;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END $$;


