CREATE TABLE public.users (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    username character varying(100) NOT NULL,
    email character varying(255) NOT NULL,
    password_hash character varying(255) NOT NULL,
    role public.user_role NOT NULL,
    first_name character varying(100),
    last_name character varying(100),
    is_active boolean DEFAULT true,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    organization_id uuid,
    plant_id uuid,
    session_version integer DEFAULT 0 NOT NULL,
    CONSTRAINT users_normalized_username CHECK ((((username)::text = lower(btrim((username)::text))) AND ((username)::text ~ '^[a-z0-9][a-z0-9._@-]*$'::text))),
    CONSTRAINT users_role_plant_scope CHECK (((((role)::text = 'SUPER_ADMIN'::text) AND (plant_id IS NULL) AND (organization_id IS NULL)) OR (((role)::text <> 'SUPER_ADMIN'::text) AND (plant_id IS NOT NULL) AND (organization_id IS NOT NULL))))
);


