    product_id uuid NOT NULL,
    target_quantity integer NOT NULL,
    completed_quantity integer DEFAULT 0 NOT NULL,
    scrap_quantity integer DEFAULT 0 NOT NULL,
    planned_start timestamp with time zone NOT NULL,
    planned_end timestamp with time zone NOT NULL,
    actual_start timestamp with time zone,
    actual_end timestamp with time zone,
    status text DEFAULT 'DRAFT'::text,
    created_by uuid,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    plant_id uuid NOT NULL,
    revision integer DEFAULT 0 NOT NULL,
    recipe_id uuid,
    evidence_snapshot jsonb,
    reviewed_snapshot jsonb,
    completed_by uuid,
    reviewed_by uuid,
    shortfall_approval jsonb,
    legacy_unverified boolean DEFAULT false NOT NULL,
    CONSTRAINT operational_order_status CHECK ((status = ANY (ARRAY['DRAFT'::text, 'PLANNED'::text, 'RELEASED'::text, 'IN_PROGRESS'::text, 'PAUSED'::text, 'COMPLETED'::text, 'REVIEWED'::text, 'CLOSED'::text])))
);


