INSERT INTO public.batch_recipes VALUES ('f1111111-0001-1111-1111-111111111111', '30111111-0004-1111-1111-111111111111', 'RT-004', 'Control Pin Assembly', 'A', 'Assembly of heat treated EN8 steel pin into control housing with functional testing and final CMM inspection', '[{"uom": "PCS", "line_no": 10, "quantity": 1.0, "component_code": "INT-002", "component_name": "Heat Treated Pin", "component_type": "INTERMEDIATE"}]', '[{"step": 1, "instruction": "Insert heat treated pin INT-002 into control pin fixture on ASM-01 press with 4.5 kN insertion load.", "work_center": "WC-ASM", "machine_code": "ASM-01", "operation_no": 10, "operation_code": "ASSY", "operation_name": "Component Assembly"}, {"step": 2, "instruction": "Perform 100% rotational torque actuation test (12 Nm ± 0.5 Nm) on TEST-01.", "work_center": "WC-TEST", "machine_code": "TEST-01", "operation_no": 20, "operation_code": "TEST", "operation_name": "Functional Test"}, {"step": 3, "instruction": "Measure outer pin diameter and concentricity on CMM QC-02 against DWG-CP-01.", "work_center": "WC-QC", "machine_code": "QC-02", "operation_no": 30, "operation_code": "FINAL", "operation_name": "Final Inspection"}]', 99.20, 'ACTIVE', NULL, '2026-10-12 04:53:05.712961+00', NULL);
INSERT INTO public.batch_recipes VALUES ('f1111111-0002-1111-1111-111111111111', '30111111-0005-1111-1111-111111111111', 'RT-005', 'Hydraulic Seal Assembly', 'A', 'Assembly of NBR 70 rubber seal and copper retaining ring with hydrostatic pressure leak testing', '[{"uom": "PCS", "line_no": 10, "quantity": 1.0, "component_code": "INT-003", "component_name": "Rubber Seal", "component_type": "INTERMEDIATE"}, {"uom": "KG", "line_no": 20, "quantity": 0.05, "component_code": "RM-ST-004", "component_name": "Copper Wire 2.5 mm", "component_type": "RAW"}]', '[{"step": 1, "instruction": "Form copper wire retaining ring and seat NBR rubber seal INT-003 on ASM-01.", "work_center": "WC-ASM", "machine_code": "ASM-01", "operation_no": 10, "operation_code": "ASSY", "operation_name": "Component Assembly"}, {"step": 2, "instruction": "Pressurize seal assembly to 250 bar hydrostatic pressure for 30 seconds on TEST-01.", "work_center": "WC-TEST", "machine_code": "TEST-01", "operation_no": 20, "operation_code": "TEST", "operation_name": "Hydrostatic Test"}, {"step": 3, "instruction": "Perform visual lip seal inspection and dimension verification on QC-02.", "work_center": "WC-QC", "machine_code": "QC-02", "operation_no": 30, "operation_code": "FINAL", "operation_name": "Final Inspection"}]', 98.80, 'ACTIVE', NULL, '2026-10-12 04:53:05.712961+00', NULL);
INSERT INTO public.batch_recipes VALUES ('f1111111-0003-1111-1111-111111111111', '30111111-0001-1111-1111-111111111111', 'RT-001', 'Steel Pin Machining', 'A', 'Machining of EN8 steel bar stock into precision pin on CNC lathe and deburring', '[{"uom": "KG", "line_no": 10, "quantity": 0.45, "component_code": "RM-ST-001", "component_name": "EN8 Steel Bar Ø25 mm", "component_type": "RAW"}, {"uom": "KG", "line_no": 20, "quantity": 0.02, "component_code": "RM-ST-001", "component_name": "EN8 Steel Bar (Scrap/Allowance)", "component_type": "RAW"}]', '[{"step": 1, "instruction": "Cut EN8 steel bar Ø25 mm to length 120 mm ± 0.5 mm on CUT-01 band saw.", "work_center": "WC-CUT", "machine_code": "CUT-01", "operation_no": 10, "operation_code": "CUT", "operation_name": "Cutting"}, {"step": 2, "instruction": "Face, turn OD to 24.00 mm ± 0.02 mm, drill center, and chamfer on CNC-01 lathe.", "work_center": "WC-CNC", "machine_code": "CNC-01", "operation_no": 20, "operation_code": "CNC", "operation_name": "CNC Turning"}, {"step": 3, "instruction": "Tumble deburr machined pins in ceramic media on DBR-01 for 15 minutes.", "work_center": "WC-DBR", "machine_code": "DBR-01", "operation_no": 30, "operation_code": "DEBURR", "operation_name": "Deburring"}]', 97.50, 'ACTIVE', NULL, '2026-10-12 04:53:05.712961+00', NULL);
INSERT INTO public.batch_recipes VALUES ('f1111111-0004-1111-1111-111111111111', '30111111-0002-1111-1111-111111111111', 'RT-002', 'Heat Treatment', 'A', 'Induction case hardening and oil quenching of machined steel pins', '[{"uom": "PCS", "line_no": 10, "quantity": 1.0, "component_code": "INT-001", "component_name": "Machined Steel Pin", "component_type": "INTERMEDIATE"}]', '[{"step": 1, "instruction": "Induction harden at 860°C, polymer quench, and temper at 220°C to achieve 45-50 HRC surface hardness on HT-01.", "work_center": "WC-HT", "machine_code": "HT-01", "operation_no": 10, "operation_code": "HT", "operation_name": "Heat Treatment"}]', 99.50, 'ACTIVE', NULL, '2026-10-12 04:53:05.712961+00', NULL);
INSERT INTO public.batch_recipes VALUES ('f1111111-0005-1111-1111-111111111111', '30111111-0003-1111-1111-111111111111', 'RT-003', 'Rubber Moulding', 'A', 'Compression moulding and visual QA of NBR 70 Shore A rubber seals', '[{"uom": "KG", "line_no": 10, "quantity": 0.08, "component_code": "RM-ST-003", "component_name": "NBR Rubber Compound", "component_type": "RAW"}]', '[{"step": 1, "instruction": "Compression mould rubber compound preform at 170°C, 150 bar for 4.5 minutes on RM-01.", "work_center": "WC-RM", "machine_code": "RM-01", "operation_no": 10, "operation_code": "MOULD", "operation_name": "Rubber Moulding"}, {"step": 2, "instruction": "Inspect seal lip profile for flashes, voids, and tears on optical station QC-01.", "work_center": "WC-QC", "machine_code": "QC-01", "operation_no": 20, "operation_code": "VISUAL", "operation_name": "Visual Inspection"}]', 98.00, 'ACTIVE', NULL, '2026-10-12 04:53:05.712961+00', NULL);
INSERT INTO public.batch_recipes VALUES ('70111111-0006-1111-1111-111111111111', '30111111-0006-1111-1111-111111111111', 'REC-SEAT-101', 'Front Driver Seat Assembly (AutoComfort)', 'A', 'Progressive 6-station lean flow seat cell assembly for automotive driver seat with integrated recliner, ergonomic high-density foam, leatherette trim, and end-of-line functional inspection.', '[{"uom": "PCS", "purpose": "Structural chassis", "quantity": 1, "component_code": "FRAME-LH-101", "component_name": "Driver-side seat frame"}, {"uom": "SET", "purpose": "Fore-aft sliding mechanism", "quantity": 1, "component_code": "RAIL-LH-201", "component_name": "Seat slider rail kit"}, {"uom": "SET", "purpose": "Floor mounting brackets", "quantity": 1, "component_code": "BRKT-LH-301", "component_name": "Mounting bracket kit"}, {"uom": "PCS", "purpose": "Backrest angle adjust", "quantity": 1, "component_code": "RECL-101", "component_name": "Recliner mechanism"}, {"uom": "PCS", "purpose": "Operator manual control lever", "quantity": 1, "component_code": "LEVR-101", "component_name": "Adjustment lever"}, {"uom": "SET", "purpose": "M8/M10 flange bolts & torx screws", "quantity": 1, "component_code": "FAST-101", "component_name": "Fastener kit"}, {"uom": "PCS", "purpose": "High-density molded PU cushion", "quantity": 1, "component_code": "FOAM-CSH-101", "component_name": "Seat cushion foam"}, {"uom": "PCS", "purpose": "High-density molded PU backrest", "quantity": 1, "component_code": "FOAM-BST-101", "component_name": "Backrest foam"}, {"uom": "PCS", "purpose": "Premium perforated leatherette", "quantity": 1, "component_code": "COV-LH-101", "component_name": "Seat cover"}, {"uom": "SET", "purpose": "Hog rings & trim retention clips", "quantity": 1, "component_code": "CLIP-TRM-101", "component_name": "Trim clips"}, {"uom": "SET", "purpose": "Side valance & bezel trim", "quantity": 1, "component_code": "TRIM-LH-101", "component_name": "Trim components"}, {"uom": "PCS", "purpose": "Adjustable headrest", "quantity": 1, "component_code": "HDRST-101", "component_name": "Headrest"}, {"uom": "SET", "purpose": "Protective plastic hinge shields", "quantity": 1, "component_code": "COV-SD-101", "component_name": "Side covers"}, {"uom": "SET", "purpose": "Wiring harness & buckle sensor", "quantity": 1, "component_code": "ACC-KIT-101", "component_name": "Specified accessories kit"}]', '[{"cpp": "Fastener Torque: 28 ?? 2 Nm, Rail Parallelism: < 0.5 mm", "step": 1, "instruction": "Scan frame, slider rails, and mounting brackets against BOM. Position on assembly jig and torque fasteners to 28 Nm.", "work_center": "WC-FRAME", "machine_code": "ST-SEAT-01", "signoff_role": "Assembly Operator", "operation_code": "ST-01", "operation_name": "Seat frame assembly"}, {"cpp": "Quadrant Engagement: 100%, Actuation Effort: 15???25 N", "step": 2, "instruction": "Scan recliner mechanism, adjustment lever, and fastener kit. Align recliner gear quadrant and torque to 35 Nm. Test smooth detent locking.", "work_center": "WC-RECL", "machine_code": "ST-SEAT-02", "signoff_role": "Assembly Operator", "operation_code": "ST-02", "operation_name": "Recliner mechanism fitting"}, {"cpp": "Listing Wire Retention: 100%, Foam Gap: 0 mm", "step": 3, "instruction": "Scan seat cushion foam and backrest foam. Seat cushion foam into bottom frame pan, ensuring wire harness channels remain uninhibited.", "work_center": "WC-FOAM", "machine_code": "ST-SEAT-03", "signoff_role": "Assembly Operator", "operation_code": "ST-03", "operation_name": "Foam installation"}, {"cpp": "Seam Alignment: ??1.5 mm, Hog-ring Pitch: 45 mm", "step": 4, "instruction": "Scan seat cover, clips, and trim components. Pull cover taut over foam contours, secure with hog-rings. Inspect seam straightness and lack of wrinkles.", "work_center": "WC-UPHL", "machine_code": "ST-SEAT-04", "signoff_role": "Quality Inspector", "operation_code": "ST-04", "operation_name": "Upholstery installation"}, {"cpp": "Headrest Detent Load: 40???60 N, Circuit Resistance: < 0.5 Ohm", "step": 5, "instruction": "Scan headrest, side protective covers, and electrical accessory harness kit. Assemble headrest notch guide, snap side covers, and connect electrical buckle check.", "work_center": "WC-FASSY", "machine_code": "ST-SEAT-05", "signoff_role": "Quality Inspector", "operation_code": "ST-05", "operation_name": "Final seat assembly"}, {"cpp": "Full Stroke Slide Travel: 220 mm, Recline Range: 65?????125??", "step": 6, "instruction": "Scan completed seat serial number QR tag. Perform full functional 360 inspection checklist, verify slide travel, recline detent, and seal electronic genealogy record.", "work_center": "WC-FQC", "machine_code": "ST-SEAT-06", "signoff_role": "Quality Supervisor", "operation_code": "ST-06", "operation_name": "Final quality inspection"}]', 99.20, 'ACTIVE', '11111111-1111-1111-1111-111111111111', '2026-10-21 12:11:59.029388+00', NULL);


