INSERT INTO public.deviations VALUES ('d1111111-0002-1111-1111-111111111111', NULL, 'Raw Material EN8 Steel Bar Heat Certificate Mismatch', 'Inbound truck heat lot test certificate showed manganese percentage 0.72% vs specification 0.60-0.80% (acceptable but at low boundary).', 'MINOR', 'MATERIAL', '33333333-3333-3333-3333-333333333333', '2026-10-12 04:53:05.76052+00', 'CLOSED', 'Spectrometric analysis confirmed Mn content at 0.74%. Material conforms to IS 5517 requirements.', 'Third-party mill lab certificate clerical transcription error.', '55555555-5555-5555-5555-555555555555');


